feed:
{{- /* For consumed section, include all items; for others, limit to 20 */}}
{{- $pages := .Pages.ByLastmod.Reverse -}}
{{- if ne .Section "consumed" }}
  {{- $pages = first 20 $pages -}}
{{- end }}
{{- $self := .OutputFormats.Get "Atom" -}}
{{- $html := .OutputFormats.Get "HTML" -}}
{{- $feedTitle := .Title -}}
{{ $feedTitle | htmlEscape }}
{{ with $html }}{{ .Permalink }}{{ else }}{{ .Permalink }}{{ end }}
{{ with index $pages 0 }}{{ .Lastmod.Format "2006-01-02T15:04:05Z07:00" }}{{ else }}{{ now.UTC.Format "2006-01-02T15:04:05Z07:00" }}{{ end }}
{{- with $self }}

{{- end }}
{{- with $html }}

{{- end }}
{{- if .Description }}
{{ .Description | plainify | htmlEscape }}
{{- else if .Site.Params.description }}
{{ .Site.Params.description | plainify | htmlEscape }}
{{- end }}
Hugo
{{- range $pages }}

  {{ .Title | htmlEscape }}

  {{ .Permalink }}
  {{ .Lastmod.Format "2006-01-02T15:04:05Z07:00" }}
  {{- with .Date }}
  {{ .Format "2006-01-02T15:04:05Z07:00" }}
  {{- end }}

    {{ with .Params.author }}{{ . | htmlEscape }}{{ else }}{{ $.Site.Title | htmlEscape }}{{ end }}

  {{- with .Params.description }}
  {{ . | plainify | htmlEscape }}
  {{- else }}{{ with .Summary }}
  {{ . | plainify | htmlEscape }}
  {{- end }}{{ end }}
  {{- /* Add thumbnail image for feed readers if available */}}
  {{- $img := .Params.img | default .Params.image }}
  {{- $imgURL := "" }}
  {{- $imgType := "image/jpeg" }}
  {{- if $img }}
    {{- $imgURL = $img | absURL }}
    {{- if hasPrefix $img "http" }}
      {{- $imgURL = $img }}
    {{- end }}
    {{- if strings.HasSuffix $img ".png" }}
      {{- $imgType = "image/png" }}
    {{- else if strings.HasSuffix $img ".webp" }}
      {{- $imgType = "image/webp" }}
    {{- else if strings.HasSuffix $img ".gif" }}
      {{- $imgType = "image/gif" }}
    {{- end }}

  {{- end }}
  {{ if $imgURL }}<p><img src="{{ $imgURL }}" alt="{{ .Title | htmlEscape }}" /></p>{{ end }}{{ .Content | safeHTML }}

{{- end }}
